import urllib.request

for url in [
    "https://archive.ics.uci.edu/ml/machine-learning-databases/mammographic/",
    "https://archive.ics.uci.edu/static/public/161/mammographic+mass.zip",
]:
    try:
        r = urllib.request.urlopen(url, timeout=30)
        data = r.read()
        print(url, "->", r.status, len(data))
        if url.endswith("/"):
            print(data.decode("utf-8", "replace")[:3000])
    except Exception as e:
        print(url, "-> ERROR", e)

